import {createBoardAudio,moveSound} from './board-audio.js';
export const defaults={language:'it',theme:'dark',animation:'normal',coordinates:true,legal:true,sound:false,volume:.5,quality:'deep',coachDetail:'compact',coachTone:'warm',coachHints:true,coachFrequency:'all',coachPreset:'milo',board:'amethyst',avatarColor:'sage',avatarShape:'round',avatarEyes:'friendly',avatarAccessory:'none',coachName:'Milo'};
const choices={language:['it','en','es','fr','de'],theme:['system','light','dark'],animation:['normal','slow','off'],quality:['quick','standard','deep'],coachDetail:['guided','compact'],coachTone:['warm','direct','quiet'],coachFrequency:['all','errors'],coachPreset:['milo','astra','nox','custom'],board:['amethyst','lavender','green','walnut','slate'],avatarColor:['sage','sky','plum','sun'],avatarShape:['round','square','cat'],avatarEyes:['friendly','focused','happy'],avatarAccessory:['none','glasses','crown','headphones']};
export function sanitizeSettings(value){const out={...defaults};if(!value||typeof value!=='object')return out;for(const key of Object.keys(defaults)){if(choices[key]?.includes(value[key]))out[key]=value[key];else if(typeof defaults[key]==='boolean'&&typeof value[key]==='boolean')out[key]=value[key]}if(typeof value.coachName==='string')out.coachName=value.coachName.trim().slice(0,18)||defaults.coachName;if(typeof value.volume==='number'&&Number.isFinite(value.volume))out.volume=Math.max(0,Math.min(1,value.volume));out.quality="deep";return out}
let settings=defaults;try{settings=sanitizeSettings(JSON.parse(localStorage.getItem('plystreak-settings')))}catch{}
export const getSettings=()=>({...settings});
export function saveSettings(patch){settings=sanitizeSettings({...settings,...patch});let saved=true;try{localStorage.setItem('plystreak-settings',JSON.stringify(settings))}catch{saved=false}applySettings();window.dispatchEvent(new CustomEvent('ply-settings',{detail:settings}));return saved}
export function applySettings(){if(typeof document==='undefined')return;const root=document.documentElement;root.dataset.theme=settings.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):settings.theme;root.dataset.coordinates=String(settings.coordinates);root.dataset.legal=String(settings.legal);root.dataset.board=settings.board;root.dataset.motion=settings.animation;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',root.dataset.theme==='dark'?'#170e18':'#f7efe6')}
export const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function avatarSVG(s=settings){
 s=sanitizeSettings(s);
 const colors={sage:['#c4d0aa','#4b604e'],sky:['#b4d4df','#466579'],plum:['#d8bad1','#72516e'],sun:['#f0d09e','#80603e']};const [accent,ink]=colors[s.avatarColor];
 const silhouette=s.avatarShape==='square'?'<path d="M35 48Q35 30 53 30h54q18 0 18 18v42q0 35-45 35T35 90Z"/>':s.avatarShape==='cat'?'<path d="M35 64 32 29l27 15q21-8 42 0l27-15-3 35v26q0 35-45 35T35 90Z"/>':'<path d="M37 68Q37 30 80 30t43 38v22q0 35-43 35T37 90Z"/>';
 const eyes=s.avatarEyes==='happy'?'<path d="M57 78q7-7 14 0m18 0q7-7 14 0"/>':s.avatarEyes==='focused'?'<path d="m56 73 15 4m18 0 15-4M62 81v3m36-3v3"/>':'<path d="M63 78v7m34-7v7"/>';
 const accessory=s.avatarAccessory==='glasses'?'<g fill="none" stroke="'+ink+'" stroke-width="3"><rect x="49" y="69" width="26" height="21" rx="8"/><rect x="85" y="69" width="26" height="21" rx="8"/><path d="M75 78h10"/></g>':s.avatarAccessory==='crown'?'<path d="m53 35-5-19 20 9 12-16 12 16 20-9-5 19Z" fill="#e9a173" stroke="'+ink+'" stroke-width="3"/>':s.avatarAccessory==='headphones'?'<path d="M31 84V70a49 49 0 0 1 98 0v14M31 72h-6v22h10V72Zm98 0h6v22h-10V72Z" fill="'+accent+'" stroke="'+ink+'" stroke-width="4"/>':'';
 return `<svg viewBox="0 0 160 160" role="img" aria-label="Avatar illustrato del coach" xmlns="http://www.w3.org/2000/svg"><circle cx="80" cy="80" r="73" fill="${ink}" opacity=".12"/><path d="M33 145q6-31 32-34h30q26 3 32 34" fill="${ink}"/><path d="m67 117 13 16 13-16" fill="none" stroke="${accent}" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><g fill="${accent}" stroke="${ink}" stroke-width="3" stroke-linejoin="round">${silhouette}</g><path d="M44 63q6-34 36-34t36 34q-19-13-36-13T44 63Z" fill="${ink}"/><g fill="none" stroke="${ink}" stroke-width="4" stroke-linecap="round">${eyes}<path d="M68 99q12 9 24 0"/></g>${accessory}</svg>`;
}
const boardAudio=createBoardAudio({getPreferences:()=>settings,createContext:()=>new(window.AudioContext||window.webkitAudioContext)()});
export function playSound(kind='move'){if(typeof document!=='undefined'&&document.hidden)return false;return boardAudio.play(kind)}
export function playMoveSound(chess,move,options){return playSound(moveSound(chess,move,options))}
if(typeof window!=='undefined'){window.addEventListener('pointerdown',()=>boardAudio.unlock(),{passive:true});window.addEventListener('pointerup',()=>boardAudio.unlock(),{passive:true});window.addEventListener('keydown',()=>boardAudio.unlock());window.addEventListener('ply-settings',()=>{boardAudio.stop();boardAudio.unlock()});document.addEventListener('visibilitychange',()=>{if(document.hidden)boardAudio.stop()});applySettings();matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applySettings);window.addEventListener('storage',e=>{if(e.key==='plystreak-settings'){try{settings=sanitizeSettings(JSON.parse(e.newValue));applySettings();window.dispatchEvent(new CustomEvent('ply-settings',{detail:settings}))}catch{}}})}
